```python
import collections
import json
import os

def task_func(directory_path: str) -> dict:
    counter = collections.Counter()

    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            file_path = os.path.join(directory_path, filename)
            with open(file_path, 'r') as f:
                data = json.load(f)
                # Flatten the dictionary and count the keys
                for key in flatten_dict(data).keys():
                    counter[key] += 1

    return dict(counter)

# Helper function to flatten a nested dictionary
def flatten_dict(d, parent_key='', sep='_'):
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)
```

This script will go through every `.json` file in the given directory, load it into memory, and then flatten the dictionary (i.e., convert any nested dictionaries into a single-level dictionary where each key is separated by an underscore), counting the occurrences of each key.

Please note that this script assumes that the JSON files do not contain circular references or extremely large structures that could cause memory issues when loading them into memory. If you expect your JSON files to be very large or complex, you may need to modify this script to process the files in a more memory-efficient way.
